def create_model_field(
    model_config: ConfigDict,
    field_info: Union[FieldInfo, Optional[Field], None],
    annotation: Any,
    return_annotation: Any,
    is_scalar: bool,
    is_union: bool,
    is_list: bool,
    is_dict: bool,
    is_sequence: bool,
    is_scalar_sequence: bool,
    is_scalar_dict: bool,
    is_scalar_union: bool,
    is_scalar_sequence_union: bool,
    is_scalar_dict_union: bool,
    is_scalar_sequence_union_union: bool,
    is_scalar_dict_union_union: bool,
    is_scalar_sequence_union_union_union: bool,
    is_scalar_dict_union_union_union: bool,
    is_scalar_sequence_union_union_union_union: bool,
) -> Union[FieldInfo, Optional[Field]]:
    if field_info is None:
        return None
    model_config = _get_model_config(field_info, model_config)
    if model_config is None:
        return None
    if is_scalar:
        if is_scalar_union:
            annotation = Annotated[annotation, Field(default=None)]
        elif is_scalar_sequence_union:
            annotation = Annotated[annotation, Field(default=None)]
        elif is_scalar_dict_union:
            annotation = Annotated[annotation, Field(default=None)]
        elif is_scalar_sequence_union_union:
            annotation = Annotated[annotation, Field(default=None)]
        elif is_scalar_dict_union_union:
            annotation = Annotated[annotation, Field(default=None)]
        elif is_scalar_sequence_union_union_union:
            annotation = Annotated[annotation, Field(default=None)]
        elif is_scalar_dict_union_union_union:
            annotation = Annotated[annotation, Field(default=None)]
    return Field(
        *field_info._field_annotation_as_args,
        default=field_info._field_default,
        **model_config,
    )


def _get_model_config(
    field_info: Union[FieldInfo, Optional[Field]],
    model_config: Optional[ConfigDict] = None,
) -> Optional[ConfigDict]:
    if model_config is None:
        model_config = ConfigDict()
    if field_info is None:
        return model_config
    if isinstance(field_info, Field):
        model_config = field_info.model_config if field_info.model_config is not None else model_config
    return model_config


